        for c in range(w):
            if grid[r][c] == 1:
                if r == 0 or r == h - 1: cols.add(c)
                if c == 0 or c == w - 1: rows.add(r)
    for r in rows:
        for c in range(w): out[r][c] = 1
    for c in cols:
        for r in range(h): out[r][c] = 1
    seen=set(); components=[]; owner={}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                a,b=q.popleft(); cells.append((a,b))
                for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
                    if 0<=x<h and 0<=y<w and grid[x][y]==2 and (x,y) not in seen:
                        seen.add((x,y)); q.append((x,y))
            idx=len(components); components.append(cells)
            for cell in cells: owner[cell]=idx
    chosen=set()
    for r in rows:
        hit=[]
        for c in range(w):
            if grid[r][c]==2 and owner[(r,c)] not in hit: hit.append(owner[(r,c)])
        if len(hit)<=2: chosen.update(hit)
        elif len(hit)%2==1: chosen.add(hit[len(hit)//2])
    for c in cols:
